class Solution:
    def explain(self, question: str, options: List[str]) -> str:
        """
        :type question: str
        :type options: List[str]
        :rtype: str
        """

        # Write your code here
        import re
        import pandas as pd

        df = pd.read_csv('data.csv')

        question = re.sub('\W', '', question).lower()
        question = re.sub('(?<!^)(?:a|an|the)', '', question)

        if question not in df['Question'].values: return None
        if len(df['Answer'].values) == 0: return None

        ans = df[df['Question']==question]['Answer'].iloc[0].strip().split(' ')
        ans = [re.sub('\W', '', x).lower() for x in ans]

        for i in range(len(options)):
            options[i] = re.sub('\W', '', options[i]).lower()

        if all([x in ans for x in options]):
            return ' '.join(ans)
        elif any([x in ans for x in options]):
            return ' '.join(['other'])
        else:
            return ' '.join(['none'])
